<template>
  <section class="qag-space" :aria-label='pt("智能体协作空间")'>
    <header class="qag-hero"><div class="qag-hero-copy"><span class="qag-eyebrow">QGAUSS / A LITTLE TEAM OF POSSIBILITIES</span><h1>{{ pt("把灵感，") }}<br>{{ pt("交给一位") }}<span>{{ pt("行动搭档。") }}</span></h1><p>{{ pt("有知识，有工具，也有自己的拿手好戏。") }}<br>{{ pt("挑一位专业搭档，把下一步一起做出来。") }}</p><a class="qag-primary" href="#qag-library">{{ pt("发现我的搭档") }}<ClientIcon name="arrow" /></a><router-link v-if="auth.isAdmin" class="qag-text-link" to="/agents/manage">{{ pt("布置协作空间") }}<ClientIcon name="settings" /></router-link></div><div class="qag-solar" aria-hidden="true"><i class="qag-ring qag-ring-one"></i><i class="qag-ring qag-ring-two"></i><span class="qag-core">Q<b>LET'S MAKE<br>IT HAPPEN</b></span><span class="qag-satellite qag-satellite-one"><ClientIcon name="reasoning" /></span><span class="qag-satellite qag-satellite-two"><ClientIcon name="write" /></span><span class="qag-satellite qag-satellite-three"><ClientIcon name="spark" /></span><small>A GOOD IDEA<br>DESERVES GOOD COMPANY.</small></div></header>
    <div class="qag-stats" :aria-label='pt("协作空间概况")'><div><span>{{ pt("可见搭档") }}</span><strong>{{ summary.published ?? '—' }}</strong><small>{{ pt("每个专长，都有可能") }}</small></div><div><span>{{ pt("已经就位") }}</span><strong>{{ summary.ready ?? '—' }}<i></i></strong><small>{{ pt("连接准备好，再开始") }}</small></div><div><span>{{ pt("我的收藏") }}</span><strong>{{ summary.favorites ?? '—' }}<em>♡</em></strong><small>{{ pt("为喜欢的搭档留个位置") }}</small></div></div>
    <section id="qag-library" class="qag-library" aria-labelledby="qag-library-title"><div class="qag-library-heading"><div><span class="qag-eyebrow">WHO SHALL WE CREATE WITH?</span><h2 id="qag-library-title">{{ pt("今天，谁来加入你的小队？") }}</h2></div><label class="qag-search"><ClientIcon name="search" /><input v-model="keyword" type="search" maxlength="100" :placeholder='pt("搜名字、介绍或专长")' :aria-label='pt("搜索智能体")' /></label></div><div class="qag-filterbar"><div><button type="button" :aria-pressed="!favoritesOnly" @click="favoritesOnly=false">{{ pt("全部搭档") }}</button><button type="button" :aria-pressed="favoritesOnly" @click="favoritesOnly=true">{{ pt("♡ 我的收藏") }}</button><label><input v-model="readyOnly" type="checkbox" />{{ pt("只看已就位") }}</label></div><button type="button" :disabled="loading" @click="load">{{ pt("刷新") }}<ClientIcon name="refresh" /></button></div>
      <div v-if="loading" class="qag-loading" role="status"><BrandLoader :text='pt("正在集合你的行动小队…")' :size="44" /><div class="qag-skeleton-grid" aria-hidden="true"><span v-for="n in 6" :key="n"></span></div></div>
      <div v-else-if="error" class="qag-empty" role="alert"><span>☁</span><h3>{{ pt("搭档暂时还在路上。") }}</h3><p>{{ pt(error) }}</p><button class="qag-primary" type="button" @click="load">{{ pt("重新集合") }}<ClientIcon name="refresh" /></button></div>
      <div v-else-if="!items.length" class="qag-empty"><span>✳</span><h3>{{ favoritesOnly?pt("给喜欢的搭档，留个位置。"):keyword?pt("换个词，让灵感碰个面。"):pt("新的好搭档，正在等你布置。") }}</h3><p>{{ favoritesOnly?pt("在搭档卡片上点一下爱心，就能在这里找到。"):keyword?pt("试试更简短的名字或专长。"):pt("管理员完成连接并上架后，搭档就会出现在这里。") }}</p><button v-if="keyword||favoritesOnly||readyOnly" type="button" class="qag-primary" @click="reset">{{ pt("看看全部搭档") }}</button><router-link v-else-if="auth.isAdmin" class="qag-primary" to="/agents/manage">{{ pt("布置第一位搭档") }}<ClientIcon name="plus" /></router-link></div>
      <div v-else class="qag-card-grid"><article v-for="(agent,index) in items" :key="agent.id" class="qag-card" :class="'qag-tone-'+tone(agent.id)" :style="{'--qag-order':index%6}"><div class="qag-card-art" aria-hidden="true"><i></i><span class="qag-card-core"><ClientIcon :name="['reasoning','write','spark','layout'][index%4]" /></span><small>CREW / {{ String((page-1)*12+index+1).padStart(2,'0') }}</small><b>✦</b></div><button class="qag-favorite" type="button" :aria-label="(agent.favorited?pt(&quot;取消收藏：&quot;):pt(&quot;收藏：&quot;))+agent.name" :aria-pressed="!!agent.favorited" :disabled="busy.has(agent.id)" @click="favorite(agent)">{{ busy.has(agent.id)?'·':agent.favorited?'♥':'♡' }}</button><div class="qag-card-body"><span class="qag-ready" :class="{'is-ready':agent.ready}"><i></i>{{ pt(agentAvailability(agent)) }}</span><router-link :to="{path:'/agent/app',query:{agent:agent.id}}" class="qag-card-title"><h3>{{ agent.name }}</h3><ClientIcon name="arrowUpRight" /></router-link><p>{{ agent.description||pt("一位新的专业搭档，点开看看它的专长与问候。") }}</p><div class="qag-tags"><span v-for="tag in (agent.tags||[]).slice(0,3)" :key="tag">{{ tag }}</span></div></div><footer><span>{{ agentQuote(agent,pt).label }}</span><router-link :to="{path:'/agent/app',query:{agent:agent.id}}" :aria-label="pt(&quot;认识智能体：&quot;)+agent.name">{{ pt("认识一下") }}<ClientIcon name="arrow" /></router-link></footer></article></div>
      <nav v-if="!loading&&!error&&total>12" class="qag-pagination" :aria-label='pt("智能体分页")'><button type="button" :disabled="page<=1" @click="page--">{{ pt("上一页") }}</button><span>{{ page }} / {{ Math.max(1,Math.ceil(total/12)) }}</span><button type="button" :disabled="page*12>=total" @click="page++">{{ pt("下一页") }}</button></nav>
      <p v-if="!loading&&!error" class="qag-library-foot" role="status">{{ total }}{{ pt(" 位搭档 · 工具、知识与具体能力由各自配置决定") }}</p>
    </section>
  </section>
</template>
<script setup>
import {partnerText as pt} from "../i18n/partner.js";
import {onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {useRoute} from 'vue-router';
import {ElMessage} from 'element-plus';
import {api} from '../api/client.js';
import {useAuth} from '../stores/auth.js';
import {agentQuote,agentAvailability} from '../lib/agent-presentation.js';
import ClientIcon from '../components/reference/ClientIcon.vue';
import BrandLoader from '../components/design/BrandLoader.vue';
import '../components/design/agent-space.css';
const auth=useAuth(),route=useRoute(),items=ref([]),summary=ref({}),total=ref(0),page=ref(1),keyword=ref(String(route.query.q||'')),favoritesOnly=ref(false),readyOnly=ref(false),loading=ref(true),error=ref(''),busy=reactive(new Set());
let active=true,controller=null,revision=0,timer=null;const favoriteControllers=new Map();
function tone(id){let hash=0;for(const char of String(id))hash=(hash*31+char.codePointAt(0))>>>0;return ['violet','peach','sky','lime'][hash%4];}
async function load(){controller?.abort();controller=new AbortController();const signal=controller.signal,version=++revision,identity=auth.identityRevision;loading.value=true;error.value='';try{const query=new URLSearchParams({page:String(page.value),pageSize:'12',q:keyword.value.trim(),favorites:favoritesOnly.value?'1':'0',ready:readyOnly.value?'1':'0'});const data=await api.get('/agents?'+query,{signal});if(!active||signal.aborted||identity!==auth.identityRevision||version!==revision)return;items.value=Array.isArray(data.items)?data.items:[];total.value=Number.isSafeInteger(data.total)?data.total:0;summary.value=data.summary||{};}catch(e){if(active&&!signal.aborted&&identity===auth.identityRevision&&version===revision)error.value=e.message||'搭档列表暂未加载，请重试。';}finally{if(active&&!signal.aborted&&version===revision)loading.value=false;}}
async function favorite(agent){if(busy.has(agent.id))return;const c=new AbortController(),identity=auth.identityRevision;favoriteControllers.set(agent.id,c);busy.add(agent.id);try{const result=await api.post('/agents/'+encodeURIComponent(agent.id)+'/favorite',{favorited:!agent.favorited},{signal:c.signal});if(!active||c.signal.aborted||identity!==auth.identityRevision)return;const previous=agent.favorited;agent.favorited=!!result.favorited;if(previous!==agent.favorited&&Number.isSafeInteger(summary.value.favorites))summary.value.favorites+=agent.favorited?1:-1;if(favoritesOnly.value&&!agent.favorited)await load();}catch(e){if(active&&!c.signal.aborted&&identity===auth.identityRevision)ElMessage.error(pt(e.message||'收藏结果暂未确认，请刷新核对。'));}finally{if(favoriteControllers.get(agent.id)===c){favoriteControllers.delete(agent.id);busy.delete(agent.id);}}}
function reset(){keyword.value='';favoritesOnly.value=false;readyOnly.value=false;page.value=1;}
watch([favoritesOnly,readyOnly],()=>{if(page.value!==1)page.value=1;else void load();});watch(page,()=>{void load();});watch(keyword,()=>{clearTimeout(timer);timer=setTimeout(()=>{if(page.value!==1)page.value=1;else void load();},250);});
watch(()=>auth.identityRevision,()=>{controller?.abort();revision++;for(const c of favoriteControllers.values())c.abort();favoriteControllers.clear();busy.clear();items.value=[];summary.value={};total.value=0;if(auth.isLoggedIn)void load();});
onMounted(()=>{if(auth.isLoggedIn)void load();else loading.value=false;});onBeforeUnmount(()=>{active=false;clearTimeout(timer);controller?.abort();for(const c of favoriteControllers.values())c.abort();});
</script>
